package com.bank.flink.pf;

// A keyed event: login or transaction for an account, at an event time.
class AccountEvent {
    enum Type { LOGIN, TRANSACTION }

    private final String accountId;
    private final Type type;
    private final long eventTimeMillis;

    AccountEvent(String accountId, Type type, long eventTimeMillis) {
        this.accountId = accountId;
        this.type = type;
        this.eventTimeMillis = eventTimeMillis;
    }

    String getAccountId() { return accountId; }
    Type getType() { return type; }
    long getEventTimeMillis() { return eventTimeMillis; }
}
