package com.bank.flink.pf;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.logging.Logger;

// Models a KeyedProcessFunction: per-account state + event-time timers +
// side output for session-timeout alerts.
class SessionTimeoutFunction {
    private static final Logger log = Logger.getLogger(SessionTimeoutFunction.class.getName());
    private static final long TIMEOUT_MS = 5L * 60 * 1000;

    // Per-account keyed state: the fire-time of a pending login timer (or null).
    private final Map<String, Long> pendingTimer = new HashMap<>();
    // Side output: timeout alerts.
    private final List<String> alerts = new ArrayList<>();

    // processElement: called once per event (on a keyed stream).
    void processElement(AccountEvent e) {
        String key = e.getAccountId();
        switch (e.getType()) {
            case LOGIN:
                // register event-time timer at login + 5 minutes; store it.
                long fireAt = e.getEventTimeMillis() + TIMEOUT_MS;
                pendingTimer.put(key, fireAt);
                log.info(() -> "LOGIN " + key + " -> timer set for " + fireAt);
                break;
            case TRANSACTION:
                // activity arrived: cancel the pending timer (delete state).
                if (pendingTimer.remove(key) != null) {
                    log.info(() -> "TXN " + key + " -> timer cancelled, session healthy");
                } else {
                    log.info(() -> "TXN " + key + " -> no pending login timer");
                }
                break;
        }
    }

    // onTimer: fires when event-time watermark passes a registered timer.
    void onEventTime(long watermark) {
        Iterator<Map.Entry<String, Long>> it = pendingTimer.entrySet().iterator();
        while (it.hasNext()) {
            Map.Entry<String, Long> entry = it.next();
            if (watermark >= entry.getValue()) {
                String alert = "SESSION TIMEOUT account=" + entry.getKey()
                        + " no transaction within 5 min";
                alerts.add(alert);               // emit to side output
                log.warning(() -> alert);
                it.remove();                      // clean up state
            }
        }
    }

    List<String> getAlerts() { return alerts; }
}
