package com.bank.flink.pf;

import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class ProcessFunctionDemo {
    private static final Logger log = Logger.getLogger(ProcessFunctionDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        long min = 60L * 1000;
        SessionTimeoutFunction fn = new SessionTimeoutFunction();

        // Rajesh logs in at minute 0, transacts at minute 2 -> healthy.
        fn.processElement(new AccountEvent("SAV2001", AccountEvent.Type.LOGIN, 0));
        fn.processElement(new AccountEvent("SAV2001", AccountEvent.Type.TRANSACTION, 2 * min));

        // Priya logs in at minute 1 and never transacts -> will time out.
        fn.processElement(new AccountEvent("CUR3001", AccountEvent.Type.LOGIN, 1 * min));

        // Advance event-time watermark to minute 3: Rajesh's timer was cancelled,
        // Priya's fires at 1min + 5min = 6min, not yet.
        fn.onEventTime(3 * min);
        log.info("at 3min alerts=" + fn.getAlerts().size());

        // Advance watermark to minute 7: Priya's timeout fires.
        fn.onEventTime(7 * min);
        log.info("final alerts=" + fn.getAlerts());
    }
}

